// Startet den Abruf der GBFS-Einstiegsdatei
const cfg = global.get('cfg');
return { url: cfg.apis.gbfs };

// Liest aus der GBFS-Einstiegsdatei die URLs der benötigten Feeds
if (msg.statusCode !== 200 || typeof msg.payload !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'GBFS: HTTP ' + msg.statusCode });
    node.warn({ hinweis: 'GBFS-Einstiegsdatei nicht lesbar', statusCode: msg.statusCode, payload: msg.payload });
    return null;
}
const data = msg.payload.data || {};
// GBFS gruppiert Feeds nach Sprache: data.es.feeds, data.en.feeds, ...
const lang = data.es ? 'es' : (data.en ? 'en' : Object.keys(data)[0]);
const feeds = {};
for (const f of (data[lang] && data[lang].feeds) || []) feeds[f.name] = f.url;
if (!feeds.station_information || !feeds.station_status) {
    node.status({ fill: 'red', shape: 'ring', text: 'Feeds fehlen' });
    node.warn({ hinweis: 'station_information/station_status nicht gefunden', gefunden: Object.keys(feeds) });
    return null;
}
flow.set('feeds', feeds);
node.status({ fill: 'green', shape: 'dot', text: 'Feeds gefunden (' + lang + ')' });
return { url: feeds.station_information };

// station_information: Name, Lage, Kapazität aller Stationen.
// Wird als EINE Retained-Nachricht veröffentlicht (Stationsliste fürs Formular
// und für den Profil-Dienst). Ändert sich selten -> Abruf alle 24 h.
const cfg = global.get('cfg');
if (msg.statusCode !== 200 || typeof msg.payload !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode });
    return null;
}
const list = (msg.payload.data && msg.payload.data.stations) || [];
const out = list.map(s => ({
    id: String(s.station_id),
    name: s.name,
    lat: s.lat,
    lon: s.lon,
    capacity: s.capacity
}));
out.sort((a, b) => a.name.localeCompare(b.name, 'es'));
node.status({ fill: 'green', shape: 'dot', text: out.length + ' Stationen' });
return { topic: cfg.prefix + '/static/stations', payload: out, qos: 1, retain: true };

// Startet den Abruf von station_status (jede Minute).
// Ein Kommando auf .../cmd/bicimad/refresh leert den Cache,
// dann werden beim nächsten Abruf ALLE Stationen neu veröffentlicht.
if (typeof msg.topic === 'string' && msg.topic.endsWith('/cmd/bicimad/refresh')) {
    flow.set('lastSent', null);
    node.status({ fill: 'blue', shape: 'dot', text: 'Neu senden angefordert' });
}
const feeds = flow.get('feeds');
if (!feeds) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'warte auf Feed-URLs' });
    return null;
}
return { url: feeds.station_status };

// station_status -> ein Topic pro Station: .../live/bicimad/<station-id>
// "Report by Exception": nur Stationen, deren Werte sich geändert haben,
// werden gesendet, spätestens aber alle 10 min (damit Empfänger frische
// Zeitstempel sehen und veraltete Daten erkennen können).
const cfg = global.get('cfg');
if (msg.statusCode !== 200 || typeof msg.payload !== 'object') {
    node.status({ fill: 'red', shape: 'ring', text: 'HTTP ' + msg.statusCode });
    return null;
}
const REFRESH_MS = 10 * 60 * 1000;
const list = (msg.payload.data && msg.payload.data.stations) || [];
// Läuft gerade eine Simulation (.../sim/state), schickt der Collector keine Live-Werte,
// sondern nur seinen Heartbeat. Danach sendet er auf Kommando wieder alles (refresh).
if (flow.get('simActive')) {
    node.status({ fill: 'blue', shape: 'ring', text: 'Simulation aktiv: Live-Werte pausiert' });
    return [[{ topic: cfg.prefix + '/system/bicimad', payload: 'online', qos: 1, retain: true }]];
}
let last = flow.get('lastSent');
// Gedächtnis verwerfen, wenn sich das Präfix geändert hat (Context überlebt einen Deploy)
if (!last || last.__prefix !== cfg.prefix) last = { __prefix: cfg.prefix };
const now = Date.now();
const out = [];
for (const s of list) {
    const id = String(s.station_id);
    const v = {
        bikes: s.num_bikes_available,
        docks: s.num_docks_available,
        renting: !(s.is_renting === 0 || s.is_renting === false),
        returning: !(s.is_returning === 0 || s.is_returning === false)
    };
    const key = [v.bikes, v.docks, v.renting, v.returning].join('/');
    const prev = last[id];
    if (prev && prev.key === key && now - prev.t < REFRESH_MS) continue;
    last[id] = { key: key, t: now };
    v.ts = now;
    out.push({ topic: cfg.prefix + '/live/bicimad/' + id, payload: v, qos: 0, retain: true });
}
flow.set('lastSent', last);
// Heartbeat: bei jedem erfolgreichen Abruf "online" bestätigen (retained). Korrigiert
// einen veralteten Status, falls der Broker eine alte Last-Will-Nachricht nachliefert.
// Stürzt der Collector ab, bleibt der Heartbeat aus und der Last Will greift.
out.push({ topic: cfg.prefix + '/system/bicimad', payload: 'online', qos: 1, retain: true });
node.status({ fill: 'green', shape: 'dot',
    text: out.length + '/' + list.length + ' gesendet, ' + new Date().toLocaleTimeString('de-DE') });
return [out];

// Open-Meteo: aktuelles Wetter am Wetterpunkt (alle 10 min oder auf Kommando)
const cfg = global.get('cfg');
const p = cfg.weatherPoint;
const url = cfg.apis.meteo +
    '?latitude=' + p.lat + '&longitude=' + p.lon +
    '&current=temperature_2m,precipitation,wind_speed_10m,weather_code' +
    '&timezone=Europe%2FMadrid';
return { url: url };

// Open-Meteo-Antwort -> .../live/weather (retained)
const cfg = global.get('cfg');
const c = msg.statusCode === 200 && msg.payload && msg.payload.current;
if (!c) {
    node.status({ fill: 'red', shape: 'ring', text: 'Wetter: HTTP ' + msg.statusCode });
    node.warn({ hinweis: 'Unerwartete Open-Meteo-Antwort', payload: msg.payload });
    return null;
}
// Während einer Simulation nur Heartbeat, keine echten Wetterwerte (siehe Status publizieren)
if (flow.get('simActive')) {
    node.status({ fill: 'blue', shape: 'ring', text: 'Simulation aktiv: Wetter pausiert' });
    return [[{ topic: cfg.prefix + '/system/weather', payload: 'online', qos: 1, retain: true }]];
}
const w = {
    temp: c.temperature_2m,      // °C
    precip: c.precipitation,     // mm (letzte 15 min)
    wind: c.wind_speed_10m,      // km/h
    code: c.weather_code,        // WMO-Wettercode
    ts: Date.now(),
    source: 'open-meteo'
};
node.status({ fill: 'green', shape: 'dot', text: w.temp + ' °C, ' + w.precip + ' mm, ' + w.wind + ' km/h' });
// Heartbeat (siehe Collector BiciMAD): Status "online" bei jedem erfolgreichen Abruf
return [[
    { topic: cfg.prefix + '/live/weather', payload: w, qos: 0, retain: true },
    { topic: cfg.prefix + '/system/weather', payload: 'online', qos: 1, retain: true }
]];

// .../sim/state (retained): Läuft gerade eine Simulation?
// Dann pausieren die Collectors ihre Live-Werte, damit sich echte und simulierte
// Daten nicht abwechseln. Endet die Simulation, schickt der Simulator ein refresh-Kommando.
const s = msg.payload;
const active = !!(s && typeof s === 'object' && s.active);
flow.set('simActive', active);
node.status(active
    ? { fill: 'blue', shape: 'dot', text: 'Simulation: ' + (s.label || s.scenario) }
    : { fill: 'grey', shape: 'ring', text: 'keine Simulation' });
return null;
